function savedDisplayView(value, endpoint) {
  if (!/^\/workspace\/(?:blueprint-(?:cases|predictions)(?:[/?]|$)|research\/(?:jobs|recommend)(?:[/?]|$))/.test(endpoint)) return value;
  const displayPaths = new Set([
    'decision_label','display_notice','method','stage_label','message','error','recommendation_method',
    'limitations.*','calibration.source','calibration.formula_selection','structure.processes.*',
    'parameters.*.label','sources.*.label','candidate_groups.*.label',
    'top_candidates.*.decision_label','reference_candidates.*.decision_label',
    'blocked_candidates.*.decision_label','ranking.*.decision_label',
  ]);
  const normalizePath = path => path.replace(/^items\.\*\./, '').replace(/^result\./, '');
  function present(item, path = '', parent = null) {
    if (Array.isArray(item)) return item.map(child => present(child, path ? path + '.*' : '*', item));
    if (item && typeof item === 'object') return Object.fromEntries(Object.entries(item).map(([key, child]) => [key, present(child, path ? path + '.' + key : key, item)]));
    if (typeof item !== 'string' || !Object.hasOwn(savedDisplayEnglish, item)) return item;
    const field = normalizePath(path);
    const calibratedUnit = field === 'parameters.*.unit' && item === '\u500d' &&
      ['\u975e\u80be\u6e05\u9664\u7387\u500d\u7387','\u7ec4\u7ec7\u5206\u914d\u500d\u7387','\u53cc\u5411\u4ea4\u6362\u500d\u7387','\u8840\u7ec6\u80de\u5206\u914d\u500d\u7387'].includes(parent?.label);
    return displayPaths.has(field) || calibratedUnit ? savedDisplayEnglish[item] : item;
  }
  return present(value);
}
