function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4500)}
function apiError(data){if(typeof data.detail==='string')return data.detail;if(data.detail?.message)return data.detail.message;if(data.detail?.errors)return data.detail.errors.join('; ');return JSON.stringify(data.detail || data).slice(0,650)}
async function api(path, options={}){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),120000);try{const r=await fetch('/api'+path,{...options,signal:controller.signal,headers:{'Content-Type':'application/json',...options.headers}});if(r.status===401){showLogin();throw new Error('Your session has ended. Sign in again.')}const data=await r.json();if(!r.ok){const e=new Error(apiError(data));e.status=r.status;e.detail=data.detail;throw e}return savedDisplayView(data,path)}catch(e){if(e.name==='AbortError')throw new Error('Request timed out. Try again shortly.');throw e}finally{clearTimeout(timeout)}}
