function download(data,name,type='application/json'){const value=typeof data==='string'?data:JSON.stringify(data,null,2);const url=URL.createObjectURL(new Blob([value],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function sourceLink(value){try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))return esc(value);return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">View original source ↗</a>`}catch{return esc(value || 'No external link provided')}}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function head(title,sub,action=''){return `<div class="page-heading"><div><p class="eyebrow">PBPK RESEARCH / ${esc(location.hash.slice(1).toUpperCase()||'OVERVIEW')}</p><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function metrics(items){return `<div class="metrics">${items.map(([title,num,desc],i)=>`<div class="metric"><div class="label">${title}<span>0${i+1}</span></div><div class="number">${fmt(num)}</div><p>${desc}</p></div>`).join('')}</div>`}
function bars(rows){const max=Math.max(1,...rows.map(r=>r.count));return rows.map(r=>`<div class="stat-row"><span>${esc(label(r.label))}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(1,Number(r.count)/max*100)}%"></div></div><strong>${fmt(r.count)}</strong></div>`).join('')}
function options(values,selected='',all='All'){return `<option value="">${all}</option>`+values.map(v=>{const [value,text]=Array.isArray(v)?v:[v,label(v)];return `<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(text)}</option>`}).join('')}
function pager(page,total,length,kind,size=24){return `<div class="pagination"><span>${total==null?`${length} records on this page`:`${fmt(total)} records in total`} · Page ${page+1}</span><button data-action="${kind}-prev" ${page===0?'disabled':''}>← Previous page</button><button data-action="${kind}-next" ${(total==null?length<size:(page+1)*size>=total)?'disabled':''}>Next page →</button></div>`}
async function compounds(){if(!state.compounds.length)state.compounds=await api('/compounds/search?limit=250');return state.compounds}
async function overview(){const s=await api('/workspace/summary');state.summary=s;const c=s.counts;return head('From evidence to models to predictions.','Search drug evidence, discover public models, or design and run a new dosing scenario.','<span class="date-pill">● Live database connection</span>')+metrics([['Compounds with evidence',c.covered_compounds,`${c.compounds} compound identities`],['Available evidence',c.evidence,'Includes subsequent imports and data expansion'],['Public model versions',c.versions,`${c.families} model families · Complete catalog`],['Evidence sources',c.evidence_sources,'Original source locations and provenance retained']])+`<div class="hero"><div><p class="eyebrow">EVIDENCE TO MODEL</p><h2>Build your next PBPK study</h2><p>Start with model recommendations and examine applicability and validation. Use blueprint design to explore new dosing scenarios.</p></div><a class="primary" style="padding:11px 20px;border-radius:7px;font-size:12px" href="#recommend">Find a model ↗</a></div><div class="grid-two"><section class="panel"><div class="panel-heading"><h2>Evidence coverage</h2><a href="#compounds">View all ↗</a></div>${bars(s.evidence_types)}<p class="small muted">Based on imported automatically validated evidence</p></section><section class="panel"><div class="panel-heading"><h2>Continue your research</h2><span class="small muted">WORKFLOW</span></div>${[['recommend','01','Find suitable models','PBPK-Match light ranking and applicability checks'],['blueprints','02','Design and predict','Inspect blueprint structure and predict a new dosing regimen'],['compounds','03','Search drug evidence','Parameters, study conditions, and original sources']].map(([p,n,t,d])=>`<a class="quick-link" href="#${p}"><span class="quick-icon">${n}</span><div><h3>${t}</h3><p>${d}</p></div><span>↗</span></a>`).join('')}</section></div><section class="panel"><div class="panel-heading"><h2>Evidence by compound</h2><span class="small muted">TOP 8 · by evidence count</span></div><div class="form-grid"><div>${bars(s.coverage.slice(0,4))}</div><div>${bars(s.coverage.slice(4,8))}</div></div></section>`}
function evidenceTable(rows){return table(['Compound / Evidence type','Parameter and value','Context','Source',''],rows.map(r=>`<tr><td><strong>${esc(r.compound_name)}</strong><small>${esc(label(r.evidence_type))}</small></td><td>${esc(r.parameter_name)}<small>${esc(r.numeric_value??r.value_text??'No numerical value extracted')} ${esc(r.unit)}</small></td><td>${esc((r.context||'Not recorded').slice(0,100))}</td><td>${badge(r.source_id,'neutral')}</td><td><a data-action="evidence-source" data-id="${esc(r.evidence_id)}" href="/api/workspace/evidence/${encodeURIComponent(r.evidence_type)}/${encodeURIComponent(r.evidence_id)}/source" target="_blank" rel="noopener noreferrer">View source ↗</a></td></tr>`))}
async function compoundPage(){const all=await compounds();let html=head('Compounds and evidence','Browse compound information and trace each parameter to its scientific evidence.')+`<div class="tabs"><button data-action="tab-compounds" class="${state.compoundTab==='compounds'?'selected':''}">Compound directory</button><button data-action="tab-evidence" class="${state.compoundTab==='evidence'?'selected':''}">Evidence search</button></div>`;if(state.compoundTab==='compounds'){const rows=all.filter(r=>(!state.onlyCovered||r.evidence_count>0)&&JSON.stringify([r.preferred_name,r.synonyms]).toLowerCase().includes(state.compoundQ.toLowerCase()));return html+`<form id="compound-form" class="filters"><label>Find a compound<input name="q" value="${esc(state.compoundQ)}" placeholder="Drug name or synonym, e.g. midazolam"></label><label>Scope<select name="coverage"><option value="covered" ${state.onlyCovered?'selected':''}>Compounds with available evidence</option><option value="all" ${!state.onlyCovered?'selected':''}>All registered identities</option></select></label><button class="primary">Search</button></form><p class="small muted">${rows.length} compounds · Evidence is automatically validated. Identity registration does not establish evidence coverage.</p>`+table(['Compound','Evidence records','Clinical PK','PubChem',''],rows.map(r=>`<tr><td><strong>${esc(r.preferred_name)}</strong><small>${esc(list((r.synonyms||[]).slice(0,2))).slice(0,120)}</small></td><td>${fmt(r.evidence_count)}</td><td>${fmt(r.clinical_pk_count)}</td><td>${esc(r.pubchem_cid||'—')}</td><td><button data-action="compound-detail" data-id="${esc(r.compound_id)}">View details ↗</button></td></tr>`))}
const params={compound:state.evidenceCompound,q:state.evidenceQ,evidence_type:state.evidenceType,source_id:state.evidenceSource,offset:state.evidencePage*25,limit:25};const rows=await api('/evidence/search?'+query(params));state.lastEvidence=rows;return html+`<form id="evidence-form" class="filters"><label>Compound<select name="compound">${options(all.filter(c=>c.evidence_count).map(c=>[c.preferred_name,c.preferred_name]),state.evidenceCompound)}</select></label><label>Evidence type<select name="type">${options(['physicochemical','adme','clinical_pk','ddi','special_population','tissue_expression'],state.evidenceType)}</select></label><label>Source<select name="source">${options((state.summary?.sources||[]).map(x=>x.label),state.evidenceSource)}</select></label><label>Keyword<input name="q" value="${esc(state.evidenceQ)}" placeholder="Parameter, enzyme, or source-text keyword"></label><button class="primary">Search evidence</button></form><div class="inline-actions" style="margin-bottom:16px">${downloadButton('evidence-export','Export matching evidence')}</div>`+(rows.length?evidenceTable(rows):empty('No evidence matches these filters.'))+pager(state.evidencePage,null,rows.length,'evidence',25)}
function modelCards(rows){return `<div class="cards">${rows.map(r=>`<article class="model-card"><div style="display:flex;justify-content:space-between"><span class="model-symbol">◇</span>${badge(r.scientific_accepted?'Scientific validation recorded':r.execution_probe_status==='not_run'?'Not yet executed':'View validation record',r.scientific_accepted?'':'warn')}</div><div><h3>${esc(r.model_name)}</h3><p>${esc(r.version_label||r.external_model_version_id)}</p></div><p>${esc(list(r.compounds)||'Compound not recorded')}</p><div class="tags">${badge(r.software||'Software not recorded','neutral')}${(r.species||[]).slice(0,2).map(x=>badge(x,'neutral')).join('')}</div><div class="card-foot"><span class="small muted">${esc(list(r.routes)||'Route not recorded')}</span><button data-action="model-detail" data-id="${esc(r.model_version_id)}">Details ↗</button></div></article>`).join('')}</div>`}
async function modelPage(){const data=await api('/workspace/models?'+query({q:state.modelQ,software:state.modelSoftware,status:state.modelStatus,offset:state.modelPage*24,limit:24}));return head('Public models','Search all imported versions. Catalog registration, engineering execution, and scientific validation are reported separately.',downloadButton('models-export','Export model catalog'))+`<form id="model-form" class="filters"><label style="flex:2">Model or compound<input name="q" value="${esc(state.modelQ)}" placeholder="Search the catalog, e.g. Metformin, Midazolam"></label><label>Execution status<select name="status">${options([['not_run','Not yet executed'],['passed','Execution check passed']],state.modelStatus)}</select></label><button class="primary">Search models</button></form><p class="small muted">Found ${fmt(data.total)} versions · Versions in one family are not independent models</p>`+(data.items.length?modelCards(data.items):empty('No model version matches these filters.'))+pager(state.modelPage,data.total,data.items.length,'models')}
function requestForm(all){const r=state.lastRequest||{};return `<form id="recommend-form" class="panel"><div class="panel-heading"><h2>Describe your modeling request</h2><span class="small muted">MODELING REQUEST</span></div><div class="form-grid"><label>Compound<select name="compound" required>${options(all.map(c=>[c.preferred_name,c.preferred_name]),r.compound||'midazolam','Select an option')}</select></label><label>Study objective<select name="objective">${options(['base_pk','ddi_victim','ddi_perpetrator','renal_impairment','hepatic_impairment','pediatric','tissue_exposure','public_model_reuse'],r.objective||'base_pk','Select an option')}</select></label><label>Route<select name="route">${options([['oral','Oral'],['intravenous','Intravenous']],r.route||'','Any')}</select></label><label>Target population<input name="population" value="${esc(r.population||'')}" placeholder="e.g. healthy adult / pediatric"></label><label class="full">Additional constraints<textarea name="constraints" placeholder="Target tissue, enzyme/transporter, prediction endpoints, etc.">${esc(r.constraints||'')}</textarea></label></div><div class="inline-actions" style="margin-top:20px"><button class="primary" type="submit">${state.recommendTab==='models'?'Recommend public models':'Find saved component recommendations'} →</button></div></form>`}
function rankingResult(r){const summary=r.candidate_summary||{};return `<div class="result-title"><h2>Model matching results</h2>${badge(r.decision==='reuse'?'Reusable within the validated scope':'Adaptation or further validation needed','warn')}<button data-action="ranking-export">Download results ↓</button></div><p class="small muted">Scanned ${fmt(summary.catalog_scanned)} versions · Relevant ${fmt(summary.relevant_candidates)} · Same compound ${fmt(summary.same_compound)}</p><div class="note">These checks assess intended use and model conditions. Learned rankings do not override license, asset, scope, or scientific validation requirements.</div>`+(r.candidates?.length?table(['Rank','Candidate model','Applicability','Structural matching score',''],r.candidates.map((c,i)=>`<tr><td>${i+1}</td><td><strong>${esc(c.model_name)}</strong><small>${esc(c.software||'Software not recorded')} · ${esc(list(c.routes)||'Route not recorded')}</small></td><td>${badge(label(c.candidate_layer||c.recommendation_tier),'warn')}<small>${esc((c.hard_blockers||[]).slice(0,2).map(x=>label(x.reason_code||x)).join('; '))}${(c.hard_blockers||[]).length>2?' ('+c.hard_blockers.length+' blockers in total)':''}</small></td><td>${c.matching_score==null?'—':Number(c.matching_score).toFixed(3)}</td><td><button data-action="model-detail" data-id="${esc(c.model_version_id)}">Details</button></td></tr>`)):empty('No candidate meets the current request.'))+jsonView(r,'View full constraints, exclusion reasons, and method details')}
const componentNames = {compound_identity:'Compound identity',physicochemical:'Physicochemical properties',absorption:'Absorption',distribution:'Distribution',metabolism:'Metabolism',excretion:'Excretion and clearance',ddi:'Drug interactions',special_population:'Special populations',public_model_template:'Public model template',transport:'Transport'};
const componentName = value => componentNames[value] || label(value);
const scenarioNames = {oral:'Oral',intravenous:'Intravenous',human:'Human',parent:'Parent drug',parent_metabolite:'Parent drug and metabolites',whole_body:'Whole-body PBPK',reduced:'Reduced PBPK',unspecified:'Unspecified'};
const scenarioName = value => scenarioNames[value] || value;
function savedTime(value){const t=new Date(value);return value&&!Number.isNaN(t.getTime())?t.toISOString().slice(0,19).replace('T',' ')+' UTC':'Time not recorded'}
function componentScenario(request={}){
  return [scenarioName(request.route)||'Route unspecified',scenarioName(request.species),request.population,
    request.victim_drug ? 'Victim drug: '+request.victim_drug : '',
    request.perpetrator_drug ? 'Interacting drug: '+request.perpetrator_drug : ''].filter(Boolean).join(' · ');
}
function componentSearchForm(all){
  return `<form id="component-form" class="panel"><h2>Find saved component recommendations</h2><div class="filters">
    <label>Compound<select name="compound">${options(all.map(c=>[c.preferred_name,c.preferred_name]),state.componentCompound||'')}</select></label>
    <label>Study objective<select name="objective">${options(['base_pk','ddi_victim','ddi_perpetrator','renal_impairment','hepatic_impairment','pediatric','tissue_exposure','public_model_reuse'],state.componentObjective||'')}</select></label>
    <label>Route<select name="route">${options([['oral','Oral'],['intravenous','Intravenous'],['unspecified','Unspecified']],state.componentRoute||'')}</select></label>
    <button class="primary" type="submit">Find component recommendations →</button></div></form>`;
}
function componentSource(c){
  return c.evidence_id&&c.evidence_type ? `<a href="/api/workspace/evidence/${encodeURIComponent(c.evidence_type)}/${encodeURIComponent(c.evidence_id)}/source" target="_blank" rel="noopener noreferrer">View source ↗</a>` : '';
}
const parameterNames={cmax:'Peak concentration (Cmax)',tmax:'Time to peak (Tmax)',auc:'Exposure (AUC)',half_life:'Half-life', 'half-life':'Half-life',clearance:'Clearance',volume_of_distribution:'Volume of distribution',excretion_unchanged:'Unchanged drug excretion',excretion:'Excretion',logp:'Lipophilicity (logP)',alogp:'Lipophilicity (ALogP)',bioavailability:'Bioavailability','protein binding':'Protein binding','CYP3A substrate':'CYP3A substrate'};
const parameterName=value=>parameterNames[value]||parameterNames[String(value).toLowerCase()]||value;
function parameterValue(p){
  const value=p.value??p.canonical_value;
  if(value!=null)return String(value)+(p.canonical_unit||p.unit?' '+(p.canonical_unit||p.unit):'');
  if(p.value_low!=null||p.value_high!=null)return `${p.value_low??'…'} – ${p.value_high??'…'}${p.canonical_unit||p.unit?' '+(p.canonical_unit||p.unit):''}`;
  return 'No usable value provided';
}
function componentDetail(r){
  const d=r.recommendation_json||r;
  const request=d.resolved_modeling_request||r.request_json||{};
  const components=d.component_recommendations||d.recommended_components||d.components||[];
  const citations=d.citations||[];
  const parameters=d.parameter_candidates||[];
  const structure=d.recommended_model_structure||{};
  const named=rows=>(rows||[]).map(x=>typeof x==='string'?x:x.preferred_name||x.name).filter(Boolean);
  const fields={};
  if(structure.whole_body_or_reduced_pbpk)fields['Model scope']=scenarioName(structure.whole_body_or_reduced_pbpk);
  if(structure.parent_or_parent_metabolite)fields['Drug representation']=scenarioName(structure.parent_or_parent_metabolite);
  if(structure.required_compartments?.length)fields['Compartments']=structure.required_compartments;
  if(d.metabolism_pathways?.length)fields['Metabolic enzymes']=named(d.metabolism_pathways);
  if(d.transport_pathways?.length)fields['Transporters']=named(d.transport_pathways);
  if(d.special_population_adjustments?.length)fields['Populations']=named(d.special_population_adjustments);
  const statusNames={evidence_supported_candidate:'Evidence supported',recommended:'Recommended candidate',conditional:'Conditional candidate',insufficient_evidence:'Insufficient evidence'};
  const cards=components.map(c=>{
    const refs=citations.filter(x=>(c.evidence_ids||[]).includes(x.evidence_id));
    const bound=parameters.filter(x=>(c.evidence_ids||[]).includes(x.evidence_id));
    const mentioned=[...new Set(refs.map(x=>parameterName(x.parameter)).filter(Boolean))];
    const content=[];
    if(c.component==='metabolism'&&d.metabolism_pathways?.length)content.push('Metabolic enzymes: '+named(d.metabolism_pathways).join(', '));
    if(c.component==='transport'&&d.transport_pathways?.length)content.push('Transporters: '+named(d.transport_pathways).join(', '));
    if(c.component==='distribution'&&structure.required_compartments?.length)content.push('Compartments: '+structure.required_compartments.join(', '));
    if(c.component==='special_population'&&d.special_population_adjustments?.length)content.push('Populations: '+named(d.special_population_adjustments).join(', '));
    if(c.component==='public_model_template'&&d.selected_public_models?.length)content.push('Model: '+d.selected_public_models.map(m=>m.name).filter(Boolean).join(', '));
    if(mentioned.length)content.push('Evidence covers: '+mentioned.join(', '));
    const rationale=c.rationale||c.reason||c.description;
    return `<article class="component-card" data-component="${esc(c.component||'')}"><header><h3>${esc(componentName(c.component||c.name||c.component_name))}</h3>${badge(statusNames[c.status]||label(c.status),c.status==='insufficient_evidence'?'warn':'')}</header>
      ${content.map(t=>`<p>${esc(t)}</p>`).join('')}${rationale?`<p>${esc(rationale)}</p>`:''}
      ${bound.length?`<div class="tags">${bound.map(p=>badge((parameterName(p.parameter)||'Parameter')+': '+parameterValue(p),'neutral')).join('')}</div>`:'<p class="small muted">No parameter candidate has passed numerical checks for this component.</p>'}
      <details><summary>Linked evidence (${fmt(refs.length)})</summary><div class="record-list">${refs.length?refs.map(x=>`<article><h3>${esc(parameterName(x.parameter)||label(x.evidence_type))} · ${esc(x.source_id)}</h3><p>${esc(x.supporting_text||x.source_text||'No source excerpt saved')}</p>${componentSource(x)}</article>`).join(''): '<p>No linked evidence details were saved.</p>'}</div></details></article>`;
  }).join('');
  const extraCitations=citations.filter(x=>!components.some(c=>(c.evidence_ids||[]).includes(x.evidence_id)));
  const gaps=(d.evidence_gaps||[]).map(g=>typeof g==='string'&&g.startsWith('missing_component:')?'Missing evidence for '+componentName(g.slice(18)):g==='no_reusable_public_model'?'No reusable public model is available':textValue(g));
  const context=p=>{const v=p.study_context||{};return [scenarioName(p.species||v.species),p.population||v.population,scenarioName(p.route||v.route),p.dose||v.dose,v.condition].filter(Boolean).join(' · ')||'Check the original study conditions'};
  return `<div class="note">Saved recommendation · ${esc(label(r.objective||request.objective))} · ${esc(componentScenario(request))}<br>${fmt(components.length)} component categories · ${fmt(parameters.length)} parameter candidates · ${fmt(citations.length)} citations</div>
    <p class="small muted">These evidence-supported component and parameter candidates have not yet been calibrated or validated in simulation.</p>
    <section class="component-section"><h2>Model structure and mechanisms</h2><p class="small muted">These records do not yet specify an absorption equation or distribution model form.</p>${Object.keys(fields).length?kv(fields):'<p class="muted small">This record does not specify compartments or mechanisms.</p>'}</section>
    <section class="component-section"><h2>Specific components</h2><div class="component-cards">${cards||empty('No component content was saved for this record.')}</div></section>
    <section class="component-section"><h2>Parameter candidates</h2><p class="small muted">Cmax and half-life are observed endpoints; interpret each value under its original dosing and population conditions.</p>${parameters.length?table(['Parameter or endpoint','Value and unit','Evidence conditions','Source'],parameters.map(p=>`<tr><td>${esc(parameterName(p.parameter))}</td><td>${esc(parameterValue(p))}</td><td>${esc(context(p))}</td><td>${componentSource({...citations.find(c=>c.evidence_id===p.evidence_id),...p})}</td></tr>`)):'<p class="small muted">No parameter passed numerical checks. Source citations may still inform mechanism assessment.</p>'}
    ${d.parameter_candidate_rejections?.length?`<p class="small muted">Another ${fmt(d.parameter_candidate_rejections.length)} numerical bindings failed validation and are not shown as parameters.</p>`:''}</section>
    ${d.ddi_mechanisms?.length?`<section class="component-section"><h2>Interaction mechanisms</h2>${d.ddi_mechanisms.map(m=>`<p>${esc(m.trigger_text||'Mechanism not specified')}</p>`).join('')}</section>`:''}
    ${extraCitations.length?`<details><summary>Other citations (${fmt(extraCitations.length)})</summary><div class="record-list">${extraCitations.map(x=>`<article><h3>${esc(parameterName(x.parameter)||label(x.evidence_type))} · ${esc(x.source_id)}</h3><p>${esc(x.supporting_text||x.source_text||'No source excerpt saved')}</p>${componentSource(x)}</article>`).join('')}</div></details>`:''}
    ${gaps.length?`<div class="note warn"><strong>Still needed</strong><ul>${gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></div>`:''}
    <details><summary>Original request and save time</summary>${kv({'Saved at':savedTime(r.created_at),'Study objective':label(r.objective||request.objective),'Study scenario':componentScenario(request),'Dose':request.dose!=null?String(request.dose)+' '+(request.dose_unit||''):null,'Additional constraints':request.constraints})}</details>
    <button data-action="detail-export">Download recommendation JSON ↓</button>`;
}
async function savedRecommendPage(){const all=(await compounds()).filter(c=>c.evidence_count);let html=head('Recommendations','Explore component evidence and model applicability for the study objective.')+`<div class="tabs"><button data-action="tab-rank" class="${state.recommendTab==='models'?'selected':''}">Model recommendations</button><button data-action="tab-components" class="${state.recommendTab==='components'?'selected':''}">Component recommendations</button></div>`;if(state.recommendTab==='components'){const saved=await api('/recommendation/validated?'+query({limit:500,compound:state.componentCompound,objective:state.componentObjective}));
const rows=saved.filter(r=>!state.componentRoute||(r.request_json?.route||'unspecified')===state.componentRoute);
state.components=rows;
html+=`<div class="note">View saved component and parameter candidates. New component generation is currently disabled.</div>`+componentSearchForm(all)+`<p class="small muted">${fmt(rows.length)} saved recommendations · A compound may have multiple saved records. Open each to inspect its components and original request.</p>`+(rows.length?table(['Compound','Study objective','Study scenario','Saved at','Citations',''],rows.map(r=>`<tr><td>${esc(r.compound_name)}</td><td>${esc(label(r.objective))}</td><td>${esc(componentScenario(r.request_json||{}))}</td><td class="small">${esc(savedTime(r.created_at))}</td><td>${fmt(r.citation_count)}</td><td><button data-action="component-detail" data-id="${esc(r.recommendation_result_id)}">View components ↗</button></td></tr>`)):empty('No saved component recommendation matches these conditions.'));return html}return html+requestForm(all)+(state.rec?rankingResult(state.rec):`<div class="empty">Select a compound and intended use to view candidates and matching rationale.</div>`)}
async function graphPage(){const all=(await compounds()).filter(c=>c.evidence_count);const id=state.graphId||all[0]?.compound_id;const g=id?await api('/graph/compound/'+id):null;state.graph=g;return head('Knowledge graph','Explore links between a compound, its evidence, public models, and original sources.',downloadButton('graph-export','Download complete graph'))+`<form id="graph-form" class="filters"><label>Focus compound<select name="compound_id">${options(all.map(c=>[c.compound_id,c.preferred_name]),id,'Select an option')}</select></label><button class="primary">View relationships</button></form>`+(g?PBPKGraph.markup():empty('No graph available'))}
async function blueprintPage(){return PBPKBlueprint.render()}
async function recommendPage(){return state.recommendTab==='components'?savedRecommendPage():PBPKResearch.renderRecommend()}
const pages={overview,compounds:compoundPage,models:modelPage,recommend:recommendPage,blueprints:blueprintPage,graph:graphPage};
async function render(){if(disposePage){disposePage();disposePage=null}if(disposeGraph){disposeGraph();disposeGraph=null}const version=++renderVersion;const requestedRoute=location.hash.slice(1)||'overview';const route=Object.hasOwn(pages,requestedRoute)?requestedRoute:'overview';if(route!==requestedRoute)history.replaceState(null,'','#overview');const page=pages[route];$('#breadcrumb').textContent='Workspace / '+(paths[route]?.[0]||'Overview');document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('#main').innerHTML='<div class="loading">Loading research data…</div>';try{const html=await page();if(version===renderVersion){$('#main').innerHTML=html;if(route==='graph'&&state.graph)disposeGraph=PBPKGraph.mount($('#main'),state.graph,(type,id)=>api('/workspace/evidence/'+encodeURIComponent(type)+'/'+encodeURIComponent(id)));if(route==='recommend'&&state.recommendTab!=='components')disposePage=PBPKResearch.mountRecommend($('#main'));if(route==='blueprints')disposePage=PBPKBlueprint.mount($('#main'))}}catch(e){if(version===renderVersion)$('#main').innerHTML=`<div class="panel"><h2>Data are temporarily unavailable</h2><p class="error">${esc(e.message)}</p><button data-action="retry">Reload</button></div>`}}
function showLogin(){$('#login').hidden=false;$('#workspace').hidden=true}
async function openDetail(title,content){$('#detail-title').textContent=title;$('#detail-body').innerHTML=content;$('#detail').showModal()}
function kv(obj){return `<dl>${Object.entries(obj).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(list(v)||'Not recorded')}</dd>`).join('')}</dl>`}
function modelDetail(r){const v=r.version;return `<div class="tags">${badge(v.software||'Software not registered','neutral')}${badge(v.version_label||'Current version','neutral')}</div>`+kv({'Compound':v.compounds,'Species':v.species,'Population':v.populations,'Route':(v.routes||[]).map(scenarioName),'Formulation':v.formulations,'Enzymes':v.enzymes,'Transporters':v.transporters,'License':v.license_spdx_id||label(v.license_status)})+`<p>${sourceLink(v.repository_url)}</p><h3>Model structure and documentation</h3><div class="model-dossier">${[['Simulation scenarios',v.simulation_count],['Parameter records',v.parameter_record_count],['Component records',v.component_record_count],['Dataset references',v.dataset_reference_count]].map(([name,n])=>`<div class="validation-row"><span>${name}</span><strong>${fmt(n)}</strong></div>`).join('')}</div>`+kv({'Compartments':v.compartments,'Processes':v.process_types,'Outputs':v.output_names})+`<h3>Execution and validation</h3>`+kv({'Static parsing':label(v.static_parse_status),'Execution check':label(v.execution_probe_status)})+`<div class="note warn">${r.validation.some(x=>x.scientific_accepted)?'This version has a scientific validation record. Check its intended use and scope.':'This version has no passed scientific validation record. Registration alone does not permit direct prediction use.'}</div>`+(r.validation.length?table(['Engineering execution','Scientific validation','GMFE','Validation datasets'],r.validation.map(x=>`<tr><td>${x.engineering_accepted?'Passed':'Not passed'}</td><td>${x.scientific_accepted?'Passed':'Not passed'}</td><td>${x.pooled_gmfe==null?'—':esc(x.pooled_gmfe)}</td><td>${fmt(x.verification_dataset_count)}</td></tr>`)):'')+jsonView(r,'Expand original model record')}
async function exportEvidence(){const r=await post('/exports/evidence',{compound:state.evidenceCompound,evidence_type:state.evidenceType,q:state.evidenceQ,source_id:state.evidenceSource,limit:50000});const jobs=await api('/exports/jobs?limit=20');const id=r.export_job_id||r.export_job?.export_job_id||r.job?.export_job_id||jobs.find(j=>j.export_type==='evidence_csv')?.export_job_id;if(id){const a=document.createElement('a');a.href='/api/workspace/exports/'+id+'/download';a.click();toast('Evidence export generated')}else{download(r,'evidence-export.json');toast('Export downloaded')}}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||b.tagName==='A')return;const action=b.dataset.action,id=b.dataset.id;const wasDisabled=b.disabled;b.disabled=true;try{if(action==='retry')await render();else if(action==='tab-compounds'||action==='tab-evidence'){state.compoundTab=action.slice(4);await render()}else if(action==='tab-rank'||action==='tab-components'){state.recommendTab=action==='tab-rank'?'models':'components';await render()}else if(/^(models|evidence)-(prev|next)$/.test(action)){const [kind,dir]=action.split('-');state[kind==='models'?'modelPage':'evidencePage']+=dir==='next'?1:-1;await render()}else if(action==='compound-detail'){const r=await api('/compounds/'+id);state.detailRecord=r;await openDetail(r.compound.preferred_name,kv({'PubChem':r.compound.pubchem_cid,'Synonyms':r.compound.synonyms,'InChI Key':r.compound.inchi_key})+`<div class="inline-actions"><button data-action="compound-evidence" data-name="${esc(r.compound.preferred_name)}">View all evidence →</button></div><h3 style="margin-top:25px">Evidence distribution</h3>`+bars(r.evidence_counts.map(x=>({label:x.evidence_type,count:x.record_count}))))}else if(action==='compound-evidence'){state.evidenceCompound=b.dataset.name;state.compoundTab='evidence';state.evidencePage=0;$('#detail').close();await render()}else if(action==='model-detail'){const r=await api('/workspace/models/'+id);const v=r.version;state.detailRecord=r;await openDetail(v.model_name,modelDetail(r))}else if(action==='component-detail'){const r=await api('/recommendation/validated/'+id);state.detailRecord=r;await openDetail(r.compound_name+' · Component recommendations',componentDetail(r))}else if(action==='models-export'){const r=await api('/workspace/models?limit=1000');download(r,'pbpk-model-versions.json');toast(`Exported ${r.items.length} model versions`)}else if(action==='evidence-export'){await exportEvidence()}else if(action==='ranking-export')download(state.rec,'pbpk-model-recommendation.json');else if(action==='detail-export')download(state.detailRecord,'pbpk-record.json');else if(action==='graph-export')download(state.graph,'pbpk-knowledge-graph.json')}catch(e){toast(e.message)}finally{b.disabled=wasDisabled}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['compound-form','evidence-form','model-form','component-form','recommend-form','graph-form'].includes(form.getAttribute('id')))return;event.preventDefault();const v=Object.fromEntries(new FormData(form));const button=form.querySelector('button[type="submit"],button');const previous=button?.textContent;if(button){button.disabled=true;button.textContent='Searching…'}try{if(form.id==='compound-form'){state.compoundQ=v.q;state.onlyCovered=v.coverage==='covered';await render()}else if(form.id==='evidence-form'){state.evidenceQ=v.q;state.evidenceType=v.type;state.evidenceSource=v.source||'';state.evidenceCompound=v.compound;state.evidencePage=0;await render()}else if(form.id==='model-form'){state.modelQ=v.q;state.modelStatus=v.status;state.modelPage=0;await render()}else if(form.id==='component-form'){state.componentCompound=v.compound;state.componentObjective=v.objective;state.componentRoute=v.route;await render()}else if(form.id==='recommend-form'){const payload=Object.fromEntries(Object.entries(v).filter(([,value])=>value));state.lastRequest=payload;if(state.recommendTab==='models')state.rec=await post('/recommendation/public-model-ranking',payload);else {state.componentCompound=payload.compound;state.componentObjective=payload.objective;}await render()}else if(form.id==='graph-form'){state.graphId=v.compound_id;await render()}}catch(e){toast(e.message)}finally{if(button){button.disabled=false;button.textContent=previous}}});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('#login-error').textContent='';try{const body=Object.fromEntries(new FormData(e.target));const r=await fetch('/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok){const e=new Error(apiError(data));e.status=r.status;e.detail=data.detail;throw e}e.target.reset();$('#login').hidden=true;$('#workspace').hidden=false;await render()}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}});
$('#close-detail').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')&&e.clientX<$('#detail').getBoundingClientRect().left)$('#detail').close()});
$('#logout').onclick=async()=>{if(disposePage){disposePage();disposePage=null}if(disposeGraph){disposeGraph();disposeGraph=null}await fetch('/auth/logout',{method:'POST'});state.compounds=[];state.rec=null;showLogin()};
$('#nav').innerHTML=Object.entries(paths).map(([key,[name,path]])=>`<a href="#${key}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>${name}</a>`).join('');
$('#today').textContent=new Date().toLocaleDateString('en-US',{year:'numeric',month:'2-digit',day:'2-digit'});
window.addEventListener('hashchange',()=>{if(!$('#workspace').hidden)render()});
(async()=>{try{state.summary=await api('/workspace/summary');$('#workspace').hidden=false;$('#login').hidden=true;await render()}catch{showLogin()}})();
